# Studyo 0.5.52 yamasi: (1) Dedplay Hazirlik'in "okunmaz" isareti EPUB'dan okunur, seslendirmede atlanir (metinde ve ciktilarda kalir);
# (2) dipnotun icindeki numarali liste yeni dipnot sayilmaz; (3) tirnaktan sonra gelen 3 haneli dipnot numarasi baglanir.
# 0.5.51 uzerine. Kod klasorunde: cd /DATA/AppData/dedplay-studyo/kod/studyo && python3 studyo_0552_yama.py
# Tekrar calistirilabilir: dosya zaten yeniyse ATLANDI; ne eski ne yeniyse hicbir seye dokunmadan HATA.
import base64, hashlib, os, sys, zlib
D = [
    ('kutuphane/kaynak.py', '91c33bb85114a41d80caabcaf1a3c67b', '7a8908017300424abdbd0c07bf9f8784',
     ''),
    ('kutuphane/kitap.py', '1151b662161eb604522d826b833163cb', '393232c1aa17fe5ef9f2b845eb17deac',
     ''),
    ('kutuphane/cikti.py', '529626f82a36266e9d58541b5028334e', 'daffc5c10ad8dabb284e13b3d39e429e',
     ''),
    ('kutuphane/main.py', '16cd553432305ff5b0ad62f0ea8593d9', '0f47269d165c579c6f902bbb3d27abce',
     ''),
    ('app/ses.py', '54de25ac5f1ea1940356a268c59303fb', '1978c3a24c45c047c23f4865b80cb2e1',
     ''),
    ('app/export.py', 'b16a424716887b0110db764b1a36d346', '1e810d4ee092c59a7fa663e87f819795',
     ''),
    ('app/worker.py', '9109ad4e4f1ca7999a432292c2b9646d', '262167e6cdb27d818dda6c48c9017ea4',
     ''),
    ('tests/test_0552.py', None, '0d577d3940564265e41d9861dfc1ce64',
     ''),
]
md5 = lambda p: hashlib.md5(open(p, 'rb').read()).hexdigest() if os.path.exists(p) else None
for yol, eski, yeni, _ in D:
    m = md5(yol)
    if m not in (eski, yeni):
        print('HATA:', yol, 'beklenmeyen icerik (md5', m, ') - hicbir dosya degistirilmedi'); sys.exit(1)
for yol, eski, yeni, veri in D:
    if md5(yol) == yeni:
        print('ATLANDI (zaten yeni):', yol); continue
    icerik = zlib.decompress(base64.b64decode(veri))
    assert hashlib.md5(icerik).hexdigest() == yeni
    open(yol, 'wb').write(icerik)
    print('YAZILDI:', yol, yeni)
print('TAMAM')
